  add.stop(0.35, '#ff7733');
  add.stop(0.7, '#ffcc66');
  add.stop(1, '#ffffcc');
});
energyGrad.attr({x1:'0%', y1:'0%', x2:'0%', y2:'100%'});

var arrowGroup = draw.group();
arrowGroup.rect(30, 430).move(25, 65).fill(energyGrad).stroke({color:'#333', width:1});
arrowGroup.polygon('17,65 63,65 40,18').fill(energyGrad).stroke({color:'#333', width:1});
var energyLabel = draw.text('Energy').font({size:14, family:'sans-serif', weight:'bold', fill:'#000'});
energyLabel.attr({transform:'rotate(-90 40 300)', x:40, y:300, 'text-anchor':'middle', 'dominant-baseline':'middle'});

// === REACTION PROGRESS ===
draw.text('Reaction progress').font({size:13, family:'sans-serif', fill:'#000'}).move(370, 570);
var rpGroup = draw.group();
rpGroup.line(510, 578, 630, 578).stroke({color:'#e6007e', width:2.5});
rpGroup.polygon('630,572 648,578 630,584').fill('#e6007e');

// === DASHED ENERGY LEVELS ===
draw.line(200, 385, 480, 385).stroke({color:'#333', width:1.5, dasharray:'7,5'});
draw.line(400, 438, 730, 438).stroke({color:'#333', width:1.5, dasharray:'7,5'});
draw.line(312, 72, 378, 72).stroke({color:'#333', width:1.5, dasharray:'7,5'});

// === SUBSTITUTION CURVE (black) ===
var subCurve = draw.path('M 215,385 C 250,368 298,82 345,72 C 392,62 418,238 455,268 C 492,296 528,186 575,178 C 622,170 668,375 715,438')
  .fill('none').stroke({color:'#000', width:3.2, linecap:'round', linejoin:'round'});

// === ADDITION CURVE (magenta) ===
var addCurve = draw.path('M 455,268 C 498,288 542,176 590,168 C 632,161 682,196 730,225')
  .fill('none').stroke({color:'#e6007e', width:2.8, linecap:'round', linejoin:'round'});

// === ΔG‡ ARROW ===
var dgDaggerGroup = draw.group().css('cursor','pointer');
dgDaggerGroup.line(345, 380, 345, 82).stroke({color:'#333', width:1.5});
dgDaggerGroup.polygon('339,88 345,74 351,88').fill('#333');
dgDaggerGroup.polygon('339,374 345,388 351,374').fill('#333');
var dgDaggerLabel = draw.text('ΔG\u2021').font({size:13, family:'sans-serif', fill:'#000'})
  .attr({'paint-order':'stroke', stroke:'#e8f4fd', 'stroke-width':3, 'stroke-linejoin':'round'});
dgDaggerLabel.move(312, 218);
dgDaggerGroup.on('click', function(){ showPopup('Activation Energy (ΔG\u2021)','The vertical distance from the reactant energy level to the first transition-state peak. This is the kinetic barrier that must be overcome for the reaction to proceed. A larger ΔG\u2021 means a slower reaction.'); });
dgDaggerGroup.on('mousemove', function(e){ showTooltip('ΔG\u2021 = activation energy (kinetic barrier)', e); });
dgDaggerGroup.on('mouseleave', hideTooltip);

// === ΔG° ARROW ===
var dgZeroGroup = draw.group().css('cursor','pointer');
dgZeroGroup.line(455, 388, 455, 435).stroke({color:'#333', width:1.5});
dgZeroGroup.polygon('450,392 455,385 460,392').fill('#333');
dgZeroGroup.polygon('450,431 455,438 460,431').fill('#333');
var dgZeroLabel = draw.text('ΔG°').font({size:12, family:'sans-serif', fill:'#000'})
  .attr({'paint-order':'stroke', stroke:'#e8f4fd', 'stroke-width':3, 'stroke-linejoin':'round'});
dgZeroLabel.move(425, 404);
dgZeroGroup.on('click', function(){ showPopup('Overall Free Energy Change (ΔG°)','The vertical distance from the reactant level to the product level. A negative ΔG° (products below reactants) means the reaction is thermodynamically favorable. This determines whether the reaction occurs at equilibrium.'); });
dgZeroGroup.on('mousemove', function(e){ showTooltip('ΔG° = overall free energy change (thermodynamics)', e); });
dgZeroGroup.on('mouseleave', hideTooltip);

// === STRUCTURES ===
function hexPts(cx, cy, r) {
  var pts = [];
  for (var i = 0; i < 6; i++) {
    var a = -Math.PI/2 + i * Math.PI/3;
    pts.push([cx + r*Math.cos(a), cy + r*Math.sin(a)]);
  }
  return pts;
}
function ptsStr(pts) { return pts.map(function(p){return p[0].toFixed(1)+','+p[1].toFixed(1)}).join(' '); }

// Benzene (reactant)
var benzGroup = draw.group().css('cursor','pointer');
var bzPts = hexPts(155, 415, 28);
benzGroup.polygon(ptsStr(bzPts)).fill('none').stroke({color:'#000', width:1.5});
var bzInner = 0.62;
for (var bi = 0; bi < 3; bi++) {
  var i1 = bi*2, i2 = bi*2+1;
  var a1 = -Math.PI/2 + i1*Math.PI/3, a2 = -Math.PI/2 + i2*Math.PI/3;
  benzGroup.line(155+28*bzInner*Math.cos(a1), 415+28*bzInner*Math.sin(a1),
                 155+28*bzInner*Math.cos(a2), 415+28*bzInner*Math.sin(a2))
    .stroke({color:'#000', width:1.2});
}
benzGroup.on('mousemove', function(e){ showTooltip('Benzene (C\u2086H\u2086) \u2014 aromatic reactant', e); });
benzGroup.on('mouseleave', hideTooltip);
benzGroup.on('click', function(){ showPopup('Benzene','The aromatic starting material. Its delocalized π electrons attack Br\u2082 (activated by a Lewis acid catalyst) to form the arenium intermediate.'); });

// Plus sign and Br2
draw.text('+').font({size:16, family:'sans-serif', fill:'#000'}).move(205, 408);
var br2Text = draw.text('Br').font({size:14, family:'sans-serif', fill:'#e6007e', weight:'bold'}).move(235, 408);
var br2Sub = draw.text('2').font({size:10, family:'sans-serif', fill:'#e6007e'}).move(253, 414);

// Arenium intermediate
var arenGroup = draw.group().css('cursor','pointer');
var arPts = hexPts(450, 310, 22);
arenGroup.polygon(ptsStr(arPts)).fill('none').stroke({color:'#000', width:1.5});
var arInner = 0.6;
var arEdges = [[2,3],[4,5]];
for (var ai = 0; ai < arEdges.length; ai++) {
  var ea1 = -Math.PI/2 + arEdges[ai][0]*Math.PI/3;
  var ea2 = -Math.PI/2 + arEdges[ai][1]*Math.PI/3;
  arenGroup.line(450+22*arInner*Math.cos(ea1), 310+22*arInner*Math.sin(ea1),
                 450+22*arInner*Math.cos(ea2), 310+22*arInner*Math.sin(ea2))
    .stroke({color:'#000', width:1.2});
}
// H and Br on sp3 carbon (vertex index 1 = upper right)
var sp3x = arPts[1][0], sp3y = arPts[1][1];
arenGroup.line(sp3x, sp3y, sp3x+8, sp3y-10).stroke({color:'#000', width:1});
arenGroup.text('H').font({size:9, family:'sans-serif', fill:'#000'}).move(sp3x+8, sp3y-20);
arenGroup.line(sp3x, sp3y, sp3x+14, sp3y+4).stroke({color:'#000', width:1});
arenGroup.text('Br').font({size:9, family:'sans-serif', fill:'#e6007e', weight:'bold'}).move(sp3x+15, sp3y-2);
// + sign
arenGroup.text('+').font({size:13, family:'sans-serif', fill:'#000', weight:'bold'}).move(443, 278);
arenGroup.on('mousemove', function(e){ showTooltip('Arenium ion (\u03c3-complex) \u2014 cationic intermediate', e); });
arenGroup.on('mouseleave', hideTooltip);
arenGroup.on('click', function(){ showPopup('Arenium Ion (σ-Complex)','The key intermediate: a cyclohexadienyl cation formed when benzene\u2019s π system attacks Br\u2082. One carbon becomes sp\u00b3 (bearing H and Br), breaking aromaticity. Both substitution and addition pathways branch from this shared intermediate.'); });

// Bromobenzene (substitution product)
var bbGroup = draw.group().css('cursor','pointer');
var bbPts = hexPts(680, 472, 26);
bbGroup.polygon(ptsStr(bbPts)).fill('none').stroke({color:'#000', width:1.5});
for (var bbi = 0; bbi < 3; bbi++) {
  var bi1 = bbi*2, bi2 = bbi*2+1;
  var ba1 = -Math.PI/2 + bi1*Math.PI/3, ba2 = -Math.PI/2 + bi2*Math.PI/3;
  bbGroup.line(680+26*0.62*Math.cos(ba1), 472+26*0.62*Math.sin(ba1),
               680+26*0.62*Math.cos(ba2), 472+26*0.62*Math.sin(ba2))
    .stroke({color:'#000', width:1.2});
}
// Br substituent on top vertex
var bbTop = bbPts[0];
bbGroup.line(bbTop[0], bbTop[1], bbTop[0]+5, bbTop[1]-10).stroke({color:'#000', width:1});
bbGroup.text('Br').font({size:10, family:'sans-serif', fill:'#e6007e', weight:'bold'}).move(bbTop[0]+6, bbTop[1]-20);
bbGroup.on('mousemove', function(e){ showTooltip('Bromobenzene \u2014 substitution product', e); });
bbGroup.on('mouseleave', hideTooltip);
bbGroup.on('click', function(){ showPopup('Bromobenzene','The substitution product: aromaticity is restored by loss of H\u207a (which combines with Br\u207b to give HBr). The product lies below the reactant level, making this pathway thermodynamically favorable.'); });

// + and HBr
draw.text('+').font({size:14, family:'sans-serif', fill:'#000'}).move(725, 468);
draw.text('HBr').font({size:13, family:'sans-serif', fill:'#000'}).move(750, 468);

// "Substitution" label
draw.text('Substitution').font({size:13, family:'sans-serif', fill:'#000'}).move(650, 520);

// Addition product (bracketed dibrominated ring)
var addProdGroup = draw.group().css('cursor','pointer');
var apPts = hexPts(745, 148, 24);
addProdGroup.polygon(ptsStr(apPts)).fill('none').stroke({color:'#000', width:1.5});
// Two double bonds
var apInner = 0.6;
var apEdges = [[2,3],[4,5]];
for (var api = 0; api < apEdges.length; api++) {
  var apa1 = -Math.PI/2 + apEdges[api][0]*Math.PI/3;
  var apa2 = -Math.PI/2 + apEdges[api][1]*Math.PI/3;
  addProdGroup.line(745+24*apInner*Math.cos(apa1), 148+24*apInner*Math.sin(apa1),
                    745+24*apInner*Math.cos(apa2), 148+24*apInner*Math.sin(apa2))
    .stroke({color:'#000', width:1.2});
}
// H and Br on vertex 0 (top), Br and H on vertex 1 (upper right)
var apV0 = apPts[0], apV1 = apPts[1];
addProdGroup.line(apV0[0], apV0[1], apV0[0]-5, apV0[1]-10).stroke({color:'#000', width:1});
addProdGroup.text('H').font({size:9, family:'sans-serif', fill:'#000'}).move(apV0[0]-14, apV0[1]-18);
addProdGroup.line(apV0[0], apV0[1], apV0[0]+8, apV0[1]-8).stroke({color:'#000', width:1});
addProdGroup.text('Br').font({size:9, family:'sans-serif', fill:'#e6007e', weight:'bold'}).move(apV0[0]+9, apV0[1]-14);
addProdGroup.line(apV1[0], apV1[1], apV1[0]+10, apV1[1]-4).stroke({color:'#000', width:1});
addProdGroup.text('Br').font({size:9, family:'sans-serif', fill:'#e6007e', weight:'bold'}).move(apV1[0]+11, apV1[1]-10);
addProdGroup.line(apV1[0], apV1[1], apV1[0]+8, apV1[1]+8).stroke({color:'#000', width:1});
addProdGroup.text('H').font({size:9, family:'sans-serif', fill:'#000'}).move(apV1[0]+9, apV1[1]+4);
// Brackets
addProdGroup.text('[').font({size:28, family:'sans-serif', fill:'#000'}).move(708, 128);
addProdGroup.text(']').font({size:28, family:'sans-serif', fill:'#000'}).move(774, 128);
addProdGroup.on('mousemove', function(e){ showTooltip('1,2-Dibromocyclohexadiene \u2014 addition product (not observed)', e); });
addProdGroup.on('mouseleave', hideTooltip);
addProdGroup.on('click', function(){ showPopup('Addition Product (Not Observed)','If Br\u207b added to the arenium ion instead of abstracting H\u207a, a non-aromatic dibromide would form. This product lies above the reactant level (uphill), so this pathway is thermodynamically disfavored and does not occur.'); });

// "Addition" and "(does not occur)" labels
draw.text('Addition').font({size:13, family:'sans-serif', fill:'#000'}).move(718, 240);
var doesNotOccur = draw.text('(does not occur)').font({size:12, family:'sans-serif', fill:'#e6007e', weight:'bold', style:'italic'}).move(700, 258);

// === STAGE MARKER ===
var stageMarker = draw.circle(14).fill('#ff4400').stroke({color:'#fff', width:2.5})
  .center(stagePositions[0].x, stagePositions[0].y).css('cursor','pointer');
var stageLabel = draw.text(stagePositions[0].label).font({size:10, family:'sans-serif', fill:'#ff4400', weight:'bold'})
  .attr({'paint-order':'stroke', stroke:'#e8f4fd', 'stroke-width':3, 'stroke-linejoin':'round'});
stageLabel.center(stagePositions[0].x, stagePositions[0].y - 18);

function updateStageMarker() {
  var pos = stagePositions[currentStage];
  stageMarker.center(pos.x, pos.y);
  stageLabel.text(pos.label).center(pos.x, pos.y - 18);
}

// === PATHWAY EMPHASIS ===
function updatePathwayEmphasis() {
  if (emphasizeAddition) {
    addCurve.stroke({width:3.5, color:'#e6007e'});
    addCurve.attr('opacity', 1);
    subCurve.stroke({width:2, color:'#666'});
    subCurve.attr('opacity', 0.5);
    addProdGroup.attr('opacity', 1);
    doesNotOccur.attr('opacity', 1);
  } else {
    subCurve.stroke({width:3.2, color:'#000'});
    subCurve.attr('opacity', 1);
    addCurve.stroke({width:2.2, color:'#e6007e'});
    addCurve.attr('opacity', 0.6);
    addProdGroup.attr('opacity', 0.7);
    doesNotOccur.attr('opacity', 0.7);
  }
}
updatePathwayEmphasis();

// === INTERACTION HANDLERS ===
function trigger_reactionStage() {
  currentStage = (currentStage + 1) % 5;
  updateStageMarker();
}

function toggle_pathway(checked) {
  emphasizeAddition = checked;
  updatePathwayEmphasis();
}

// === DEMO STEPS ===
var demoSteps = [
  {
    title: 'Reactants on the energy scale',
    narration: 'Benzene and Br\u2082 sit on the dashed reactant level at the left of a single vertical energy scale; everything that follows is read as a height on this scale.',
    state: {pathway: false, stage: 0}
  },
  {
    title: 'Two barriers, one intermediate',
    narration: 'Step the black curve forward: it climbs the tall first barrier (ΔG\u2021) into the cationic arenium intermediate in the trough, then a second smaller barrier, before dropping to products \u2014 substitution is a two-step, two-barrier process.',
    state: {pathway: false, stage: 2}
  },
  {
    title: 'Substitution ends downhill',
    narration: 'At the products stage the bromobenzene + HBr level lies below the reactants, so ΔG° is negative and the substitution branch is thermodynamically favored.',
    state: {pathway: false, stage: 4}
  },
  {
    title: 'Why addition does not occur',
    narration: 'Toggle to the magenta addition branch: it leaves the same intermediate but climbs to a dibrominated product that sits above the reactant level \u2014 an uphill endpoint, which is why this pathway does not occur.',
    state: {pathway: true, stage: 2}
  },
  {
    title: 'Activation energy vs overall free energy',
    narration: 'Click the tall arrow to highlight ΔG\u2021 (kinetic barrier to the first peak) and the short arrow to highlight ΔG° (thermodynamic gap to the products); they are different vertical distances on the same scale and answer different questions.',
    state: {pathway: false, stage: 4}
  }
];

var currentStep = 0;

function applyStep(idx) {
  currentStep = idx;
  var step = demoSteps[idx];
  document.getElementById('demoNarration').textContent = step.narration;
  document.getElementById('stepLabel').textContent = (idx+1) + '/' + demoSteps.length;
  currentStage = step.state.stage;
  emphasizeAddition = step.state.pathway;
  document.getElementById('pathwayInput').checked = emphasizeAddition;
  updateStageMarker();
  updatePathwayEmphasis();
}

function nextStep() {
  if (currentStep < demoSteps.length - 1) applyStep(currentStep + 1);
}

function prevStep() {
  if (currentStep > 0) applyStep(currentStep - 1);
}

applyStep(0);

window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Electrophilic bromination of benzene passes through two activation barriers and a cationic arenium intermediate, and the substitution branch is observed (while addition is not) because substitution ends downhill in free energy whereas addition ends uphill.
KEY INSIGHT (what students should walk away understanding): Substitution and addition share the same first barrier and arenium intermediate, so the deciding factor is the final step's thermodynamics: substitution ends below the reactant level (downhill, occurs) while addition ends above it (uphill, does not occur).
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
